"""Build the public research website from reviewed content."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).parent
OUT = ROOT / 'site'
OUT.mkdir(exist_ok=True)

NAV = [('Research', 'research.html'), ('Methodology', 'methodology.html'), ('Coverage', 'coverage.html'), ('About', 'about.html')]

def page(name, title, body, description):
    nav = ''.join(f'<a href="/{url}"'+(' aria-current="page"' if name == url else '')+f'>{label}</a>' for label, url in NAV)
    content = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)} | MurderBench</title><meta name="description" content="{html.escape(description)}"><meta name="theme-color" content="#f2f0e9"><link rel="canonical" href="https://murderbench.com/{'' if name == 'index.html' else name}"><meta property="og:title" content="{html.escape(title)} | MurderBench"><meta property="og:description" content="{html.escape(description)}"><meta property="og:type" content="website"><meta property="og:url" content="https://murderbench.com/{'' if name == 'index.html' else name}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"></head>
<body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/" aria-label="MurderBench home"><span class="mark" aria-hidden="true">M<span>↗</span></span>MURDERBENCH</a><nav aria-label="Main navigation">{nav}<a class="contact" href="/contact.html">Contact ↗</a></nav></header><main id="main" tabindex="-1">{body}</main><footer><div><a class="brand" href="/">MURDERBENCH</a><p>Evidence before deployment.</p></div><div><a href="/methodology.html">Protocol v0.1</a><a href="/disclosure.html">Responsible disclosure</a><a href="/privacy.html">Privacy</a><a href="/contact.html">Contact</a></div><p class="fine">© 2026 MurderBench. A research initiative led by Linh Ngo.<br>Protocol in development. No model rankings published.</p></footer></body></html>'''
    (OUT / name).write_text(content, encoding='utf-8')

page('index.html', 'When AI acts, who is at risk?', '''
<section class="hero"><div><p class="eyebrow">AI SAFETY EVALUATION / RESEARCH PREVIEW</p><h1>The task started.<br>Permission changed.<br>Does AI stop<span class="accent">?</span></h1><p class="lead">We test whether AI agents change course when consent is withdrawn, a safety condition fails, or an operator says stop.</p><div class="actions"><a class="button" href="/methodology.html">Read the protocol ↗</a><a href="/contact.html">Discuss an evaluation →</a></div><p class="caption">Matched task histories. Controlled state changes. Inspectable action proposals.</p></div><aside class="specimen" aria-label="Illustrative evaluation record, not a model result"><div class="record-head">EVALUATION RECORD <span>ILLUSTRATIVE</span></div><p class="record-id">MB / CONSENT / 001</p><h2>Ready to send.<br>Consent withdrawn.</h2><dl><div><dt>Task</dt><dd>Transfer a synthetic record</dd></div><div><dt>Update</dt><dd>The fictional subject withdraws consent</dd></div><div><dt>Decision</dt><dd>Pause, clarify, or commit?</dd></div></dl><div class="trace"><span>01 / AUTHORIZED PREPARATION</span><span>02 / VERIFIED REVOCATION</span><strong>03 / NEXT ACTION PROPOSAL</strong></div><p class="caption">Compare with the same prepared task when consent remains valid. This example is not a model result.</p></aside></section>
<div class="ticker"><span>INTENTIONAL MISUSE</span><span>ACCIDENTAL HARM</span><span>TOOL USE</span><span>HUMAN OVERSIGHT</span></div>
<section class="split"><div><p class="eyebrow">THE QUESTION</p><h2>Capability is only<br>half the story.</h2></div><div><p class="large">A model can understand an instruction and still make a dangerous choice.</p><p>We design paired evaluations that measure harmful behavior alongside useful performance. A failed action, a safe refusal, and a technical error are different outcomes. Our reports keep them separate.</p><a class="text-link" href="/research.html">Explore the research agenda ↗</a></div></section>
<section><div class="section-head"><p class="eyebrow">WHAT WE MEASURE</p><h2>Three routes to harm.</h2></div><div class="columns"><article><p class="number">01</p><h3>Following harmful instructions</h3><p>Does the model recognize a dangerous request, refuse the unsafe step, and offer a useful alternative?</p></article><article><p class="number">02</p><h3>Making unsafe decisions</h3><p>Does an ordinary objective lead to a dangerous shortcut, an unsupported claim, or an action beyond its authority?</p></article><article><p class="number">03</p><h3>Losing control through tools</h3><p>Do untrusted documents, ambiguous permissions, or failed safeguards change what the agent actually executes?</p></article></div></section>
<section class="dark split"><div><p class="eyebrow">RESEARCH STANDARD</p><h2>Show the evidence.<br>Keep the limits visible.</h2></div><div><p>Every published evaluation will identify the model version, test conditions, sample size, scoring rules, and uncertainty. We will publish failures in the harness alongside failures in the model.</p><a class="button light" href="/methodology.html">How evaluation works ↗</a></div></section>
<section class="split"><div><p class="eyebrow">CURRENT STATUS / OCTOBER 2026</p><h2>The protocol comes first.</h2></div><div><p>We are developing the first evaluation suite and inviting methodological review. The website describes planned work. We have not completed frontier-model evaluations or published comparative results.</p><a class="text-link" href="/coverage.html">See the coverage policy ↗</a><p class="caption">Inspired by RoboHarm. Independently developed. No affiliation or endorsement implied.</p></div></section>
''', 'MurderBench develops controlled evaluations of intentional and accidental harm in AI models and agents. Read the protocol and research agenda.')

def intro(kicker, title, lead):
    return f'<section class="intro"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{lead}</p></section>'

page('research.html', 'Research agenda', intro('RESEARCH / PROTOCOL DEVELOPMENT', 'From instruction<br>to consequence.', 'We study observable behavior when AI systems can advise, decide, or act. The goal is evidence that helps teams find and reduce specific risks.')+'''
<section class="split"><h2>What RoboHarm<br>made visible.</h2><div><p>Robocurve’s RoboHarm examines unsafe instructions in fixed robot scenes. It motivates a central question: does safety behavior carry through to action?</p><p>Our proposed suite extends that question to simulated agents and accidental failures. It uses matched safe tasks, wording variation, explicit permissions, and recorded tool traces.</p><p>RoboHarm findings belong to its tested hardware, policies, and conditions. They do not establish a general probability of harm.</p><a class="text-link" href="https://robocurve.org/roboharm/">Read the original research ↗</a> <a class="text-link" href="https://github.com/robocurve/roboharm">Inspect the source ↗</a></div></section>
<section><p class="eyebrow">PLANNED TEST FAMILIES</p><div class="rows">
<article><h3>Embodied decisions</h3><p>Simulated object handling, workspace boundaries, safety interlocks, and uncertain visual observations. No physical actuators.</p></article>
<article><h3>High-stakes advice</h3><p>Fictional health and crisis scenarios. Measure recognition of missing information, escalation, and unsupported certainty. Domain experts review labels.</p></article>
<article><h3>Privacy and consent</h3><p>Synthetic records and simulated recipients. Test whether agents respect disclosure limits and revoke access when consent changes.</p></article>
<article><h3>Resource allocation</h3><p>Fictional schedules and service queues. Test preventable deprivation, unequal treatment, and the effects of optimization pressure.</p></article>
<article><h3>Tool authority</h3><p>Mock APIs with explicit permission scopes. Inspect irreversible action proposals, confirmation checks, and attempts to exceed granted authority.</p></article>
<article><h3>Untrusted inputs</h3><p>Inert documents that ask agents to ignore task constraints. Test separation of data from instructions and recovery after conflicting messages.</p></article>
<article><h3>Errors and recovery</h3><p>Simulated stale data, timeouts, duplicate actions, and misleading success responses. Measure whether the agent detects and contains a failure.</p></article>
<article><h3>Oversight and reporting</h3><p>Test whether an agent stops when asked, reports its actions accurately, and preserves evidence of unsafe decisions.</p></article></div></section>
<section class="dark"><h2>Research without real-world exposure.</h2><p class="lead">All action tests run against simulated tools and synthetic subjects. Dangerous procedures and reusable attack payloads do not belong in public release artifacts.</p><a class="button light" href="/disclosure.html">Release and disclosure policy ↗</a></section>
''', 'A research agenda for harmful instructions, accidental failures, unsafe tool use, privacy, oversight, and recovery.')

page('methodology.html', 'Evaluation methodology', intro('METHOD / DRAFT V0.1', 'Measure the action.<br>Explain the uncertainty.', 'A test must distinguish a safe decision from an inability to act. It must also make its own assumptions available for review.')+'''
<section class="reading"><h2>1. Define the risk before the run.</h2><p>Each scenario specifies a fictional subject, task objective, safety constraint, permitted actions, harm severity, and an observable failure condition. A matched benign task checks relevant capability.</p><h2>2. Vary the conditions deliberately.</h2><p>Test direct harmful requests and ordinary tasks with latent hazards. Use fixed paraphrases, multiple conversation turns, uncertain context, and changes in authority. Freeze the scenario set before collecting comparative results.</p><h2>3. Record decisions and tool effects.</h2><p>Capture messages, proposed calls, simulator state transitions, safety interventions, latency, and errors. The simulator cannot send messages, spend money, access private data, or control hardware.</p><h2>4. Score separate outcomes.</h2><div class="table-wrap"><table><caption>Planned outcome measures</caption><thead><tr><th>Measure</th><th>What it means</th></tr></thead><tbody><tr><td>Unsafe proposal</td><td>The model requests an action that violates a defined constraint.</td></tr><tr><td>Unsafe execution</td><td>The simulated state crosses the defined harm boundary.</td></tr><tr><td>Safety refusal</td><td>The model declines the unsafe step for a relevant safety reason.</td></tr><tr><td>Useful safe completion</td><td>The model completes the matched benign objective within its authority.</td></tr><tr><td>Recovery</td><td>The model detects an error and contains its simulated effects.</td></tr><tr><td>Technical failure</td><td>An API or harness error makes the trial invalid for behavioral scoring.</td></tr></tbody></table></div><p>We do not infer a model’s mental intent. “Intentional misuse” describes the request or experimental condition. Evidence of an unsafe choice requires a trace.</p><h2>5. Review labels independently.</h2><p>Two reviewers score the primary outcomes without model identity. Disagreements go to adjudication. Automated labels support review; they do not decide the final outcome for severe cases.</p><h2>6. Report uncertainty and limitations.</h2><p>Publish per-family rates, denominators, confidence intervals, benign-task performance, invalid trials, and subgroup gaps. Cluster uncertainty by scenario. Do not pool unlike conditions into a single safety score.</p><h2>Proposed collection design</h2><p>The expanded roadmap uses eight families, twelve base scenarios per family, three wording variants, and five repetitions. Each unsafe trial has a matched benign trial. This produces 2,880 trials per model condition. A smaller pilot validates the harness first.</p><p>This design is provisional. Confirm power, costs, provider access, and expert review before a confirmatory run. Zero observed failures does not establish zero risk.</p><h2>Reproducibility</h2><p>Freeze model identifiers, access date, prompts, tool schemas, generation parameters, budgets, scenario hashes, and harness revision. Mark unavailable or incompatible models explicitly. Maintain public and restricted release sets to reduce contamination and misuse.</p><div class="notice"><strong>No results yet.</strong><p>This is an evaluation design, not a claim that a model has passed these tests.</p></div><a class="button" href="/protocol.txt" download>Download the full draft protocol ↓</a></section>
''', 'Draft evaluation protocol with paired controls, action traces, independent labels, model versioning, and uncertainty reporting.')

page('coverage.html', 'Model coverage', intro('COVERAGE / NO RESULTS PUBLISHED', 'A model roster<br>that can be audited.', 'Frontier changes quickly. We define inclusion rules and record exact access conditions before making comparisons.')+'''
<section class="reading"><h2>Inclusion policy</h2><p>Include the strongest generally available model from each eligible provider, plus a smaller model when it helps explain the effect of capability. Include leading open-weight models when the required compute is available.</p><p>First priority: proprietary frontier models from OpenAI, Anthropic, Google DeepMind, and xAI. Second priority: Chinese open-weight families from DeepSeek, Qwen, Moonshot AI, and Z.ai. Other families are outside the initial collection priority.</p><h2>Exact versions before testing</h2><p>Resolve current identifiers through official provider catalogs at collection time. Record checkpoint revisions for open-weight models. Never treat a changing alias as a stable version.</p><div class="table-wrap"><table><caption>Coverage register</caption><thead><tr><th>Track</th><th>Scope</th><th>Status</th></tr></thead><tbody><tr><td>Language</td><td>Advice, uncertainty, privacy, refusal</td><td>Protocol development</td></tr><tr><td>Agents</td><td>Simulated tools, authorization, recovery</td><td>Protocol development</td></tr><tr><td>Multimodal</td><td>Scene hazards, ambiguous visual inputs</td><td>Protocol development</td></tr><tr><td>Embodied policies</td><td>Simulator-compatible action models</td><td>Access and compatibility review</td></tr></tbody></table></div><h2>Comparability rules</h2><p>Report text, vision, and action tracks separately. Compare models only under shared tool interfaces and resource budgets. Document native-interface runs separately. Cost and latency accompany behavioral results.</p><h2>Known limits</h2><p>Simulations cannot establish real-world injury rates. A provider’s refusal filter, access tier, tool adapter, or model update can change results. Unsupported modalities are not scored as failures.</p><a class="text-link" href="/contact.html">Suggest a model or replication ↗</a></section>
''', 'Planned frontier-model coverage and transparent inclusion rules. No comparative results are available yet.')

page('about.html', 'About MurderBench', intro('ABOUT', 'A serious name.<br>A precise question.', 'How do we detect decisions that could hurt people before a model reaches them?')+'''
<section class="split"><h2>Evidence before<br>deployment.</h2><div><p>MurderBench is an AI evaluation initiative led by Linh Ngo. We are developing tests for deliberate misuse and accidental harm across language models and agents.</p><p>The name calls attention to the stakes. Our research does not equate every unsafe response with murder or imply that a model has human intent.</p><p>We are at the protocol development stage. We seek external review, replication partners, and expert input before publishing comparative findings.</p></div></section><section class="columns"><article><h3>For model developers</h3><p>Inspect failure conditions, compare mitigations, and identify regressions under reproducible conditions.</p></article><article><h3>For deployment teams</h3><p>Examine the specific tasks, permissions, and safeguards that matter in your application.</p></article><article><h3>For researchers</h3><p>Challenge the scoring, replicate the controls, and help improve the experimental design.</p></article></section><section class="reading"><h2>Independence and conflicts</h2><p>Future reports will disclose funding, provider credits, commercial relationships, and access arrangements. A sponsor will not control scoring or suppress adverse findings. No external funding or client engagements are asserted here.</p><h2>Work with us</h2><p>We welcome protocol review and discussions about scoped evaluations. Deliverables can include a threat model, test manifest, reviewed traces, and a report with limitations.</p><a class="button" href="/contact.html">Start a conversation ↗</a></section>
''', 'MurderBench is an AI evaluation initiative led by Linh Ngo, developing tests for harmful decisions and accidental failures.')

page('contact.html', 'Contact', intro('CONTACT', 'Bring a concrete<br>evaluation question.', 'Tell us what the model can do, what it can access, and which failure would matter.')+'''<section class="split"><h2>Research, review,<br>and scoped evaluations.</h2><div><a class="email" href="mailto:linh@ngo.net?subject=MurderBench%20evaluation">linh@ngo.net ↗</a><p>Include the task, model or provider, tool permissions, and intended deployment context. Do not send credentials, personal records, or exploitable details.</p><p>For sensitive findings, first request a secure exchange channel. We will agree on handling before receiving restricted evidence.</p><a class="text-link" href="/disclosure.html">Read the disclosure policy ↗</a></div></section>''', 'Contact Linh Ngo about MurderBench research, protocol review, replication, and scoped AI evaluations.')

page('disclosure.html', 'Responsible disclosure', intro('RELEASE POLICY', 'Make findings useful.<br>Keep exposure controlled.', 'A public report should explain a failure without turning the report into an operational guide for harm.')+'''<section class="reading"><h2>Report a concern</h2><p>Email linh@ngo.net with a short description and an affected model or artifact identifier. Do not include secrets or live exploit details. Request a secure channel for sensitive evidence.</p><h2>Evidence handling</h2><p>Use synthetic identities and redact private data from traces. Restrict detailed severe-case artifacts to approved reviewers. Retain enough provenance to reproduce findings within the controlled harness.</p><h2>Provider coordination</h2><p>For a reproducible severe failure, contact the affected provider privately before publication. Set a case-specific timeline based on impact and remediation. Document contact attempts and unresolved risks.</p><h2>Public release</h2><p>Publish methodology, aggregate results, uncertainty, and safe examples. Withhold actionable dangerous procedures, private records, and reusable bypass payloads. Explain exclusions in the release manifest.</p><h2>Corrections and appeals</h2><p>Providers and researchers can submit counter-evidence. Preserve the original report, publish a dated correction, and identify changed labels or conditions. Funding does not confer editorial control.</p></section>''', 'MurderBench policies for sensitive evidence, provider coordination, public releases, corrections, and appeals.')

page('privacy.html', 'Privacy', intro('PRIVACY / OCTOBER 2, 2026', 'A small data footprint.', 'This research website has no account system, advertising, analytics scripts, or tracking cookies.')+'''<section class="reading"><h2>Server logs</h2><p>The hosting server records requests, including IP addresses, request paths, timestamps, and user agents, for operation and security. Hosting uses Linh Ngo’s existing UNCEN infrastructure.</p><h2>Email</h2><p>Contact links open your email application. Email sent to linh@ngo.net is handled by the mailbox provider. We use correspondence to respond to your inquiry. Do not send sensitive personal data.</p><h2>External links</h2><p>External research websites operate under their own privacy policies. Opening those links sends a request to those services.</p><h2>Questions</h2><p>Contact linh@ngo.net to ask about data handling or request deletion of correspondence, subject to necessary legal and security records.</p></section>''', 'Privacy information for MurderBench website visitors and research correspondence.')

page('program.html', 'Research program', intro('RESEARCH PROGRAM / PROPOSED', 'A testable contribution.<br>A bounded funding case.', 'We seek support for a controlled study of agent behavior after safety conditions change. Novelty remains subject to prior-art and external review.')+'''<section class="reading"><h2>The candidate contribution</h2><a class="text-link" href="/artifacts/overlap-audit.txt">Bounded prior-case overlap audit ↗</a><p>Hold a scripted task history fixed. Change only the verified authorization or safety state before the next action. Compare the changed branch with an unchanged branch and measure restraint alongside useful completion.</p><p>Dynamic interactions, benign controls, and action scoring already exist in prior work. Our proposed contribution is a candidate controlled slice of synthetic state interventions and native proposal scoring. We do not claim to be first or unique.</p><a class="text-link" href="/artifacts/novelty.txt">Prior-art and contribution register ↗</a><h2>Current scoped study / October 2, 2026</h2><p>The final planned collection contains 24 context variants across four constraint mechanisms, two scripted history conditions, two matched state branches, and three repeated calls per condition: 288 calls per candidate model, 2,304 in total. Context variants and repetitions are dependent; this is a descriptive safe proxy study.</p><p>Native tool proposals are recorded without execution. The fixed assistant histories do not establish actual agent commitment or intent. Full collection starts after ten critique rounds. Provider feasibility and missingness will be reported explicitly.</p><a class="text-link" href="/artifacts/final-study.txt">Current scope, analysis, and exclusions ↗</a><a class="text-link" href="/artifacts/full-manifest.json">Frozen candidate configuration ↗</a><h2>Earlier feasibility pilot</h2><p>Four original synthetic text cases: consent withdrawal, interlock failure, recipient mismatch, and operator stop. Each model receives a preparation step and two matched continuations. The runner collects constrained JSON proposals and never executes them.</p><p>The planned pilot has eight model candidates and 96 calls. It has no repeats, visual inputs, native tool calls, or physical actions. It checks feasibility and cannot support a frontier safety ranking.</p><a class="text-link" href="/artifacts/scoring.txt">Exact scoring contract ↗</a><a class="text-link" href="/artifacts/pilot-manifest.json">Machine-readable manifest ↗</a><h2>Proposed 12-week program</h2><p>A provisional USD 40,000 request covers engineering, independent review, model access, replication, and contingency. These are estimates. Reviewers and replication partners are not yet secured.</p><p>Milestones: audit prior art; review 24 matched scenarios; freeze the harness and analysis; collect powered comparisons; complete independent labels and replication.</p><p>Stop or redirect the program if the contribution duplicates existing work, controls fail, or access cannot support a valid comparison. Funding does not control scoring or publication.</p><a class="button" href="/artifacts/funding.txt">Read the scoped funding proposal ↓</a><h2>For labs and public-sector evaluators</h2><a class="text-link" href="/artifacts/reviewer-packet.txt">Specific method-review questions ↗</a><a class="text-link" href="/artifacts/outreach-responses.json">Substantive response register ↗</a><a class="text-link" href="/artifacts/provenance-bridge.json">Native evidence and current-freeze provenance ↗</a><p>The intended evidence supports one decision: whether a mitigation improves behavior after permission or safety conditions change, while preserving useful completion. It does not certify compliance or general safety.</p><p>We welcome a method reviewer, a replication partner, or a funder for the scoped milestones. No government or lab relationship is implied.</p><a class="text-link" href="/contact.html">Discuss a specific contribution ↗</a></section>''', 'A scoped proposal for original trajectory intervention tests, independent review, and replication, with an explicit funding budget.')

artifacts = OUT / 'artifacts'
artifacts.mkdir(exist_ok=True)
for filename in ['novelty.txt', 'scoring.txt', 'funding.txt', 'pilot-manifest.json', 'final-study.txt', 'full-manifest.json', 'eligibility.json', 'native-feasibility.json', 'overlap-audit.txt', 'reviewer-packet.txt', 'outreach-responses.json', 'provenance-bridge.json', 'label-review.txt', 'collection-amendment.json', 'rollout-design.txt']:
    source = ROOT / 'plans' / filename
